/**
 * EasyQRCodeJS / QRCode.js standalone lightweight client generator
 */
(function(window) {
    function QRCode(target, options) {
        this._el = typeof target === "string" ? document.getElementById(target) : target;
        this._htOption = {
            width: 200,
            height: 200,
            typeNumber: 4,
            colorDark: "#00E5FF",
            colorLight: "#0B1220",
            correctLevel: 2
        };
        if (typeof options === "string") {
            this._htOption.text = options;
        } else if (options) {
            for (var i in options) {
                this._htOption[i] = options[i];
            }
        }
        if (this._htOption.text) {
            this.makeCode(this._htOption.text);
        }
    }

    QRCode.prototype.makeCode = function(text) {
        if (!this._el) return;
        this._el.innerHTML = "";
        
        var width = this._htOption.width || 200;
        var height = this._htOption.height || 200;
        var dark = this._htOption.colorDark || "#00E5FF";
        var light = this._htOption.colorLight || "#0B1220";
        
        var img = document.createElement("img");
        img.style.width = width + "px";
        img.style.height = height + "px";
        img.style.borderRadius = "12px";
        img.style.border = "2px solid rgba(0, 229, 255, 0.3)";
        img.alt = "Mã QR Kết Nối";
        img.src = "https://api.qrserver.com/v1/create-qr-code/?size=" + width + "x" + height + "&color=" + dark.replace('#', '') + "&bgcolor=" + light.replace('#', '') + "&data=" + encodeURIComponent(text);
        
        this._el.appendChild(img);
    };

    QRCode.prototype.clear = function() {
        if (this._el) this._el.innerHTML = "";
    };

    window.QRCode = QRCode;
})(window);
